#include <utility>
#include <vector>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
struct Traversals { vector<int> pre, in, post; };
Traversals allTraversals(TreeNode* root) {
    Traversals result;
    if (!root) return result;
    stack<pair<TreeNode*, int>> pending;
    pending.push({root, 1});
    while (!pending.empty()) {
        auto [node, phase] = pending.top();
        pending.pop();
        if (phase == 1) {
            result.pre.push_back(node->val);
            pending.push({node, 2});
            if (node->left) pending.push({node->left, 1});
        } else if (phase == 2) {
            result.in.push_back(node->val);
            pending.push({node, 3});
            if (node->right) pending.push({node->right, 1});
        } else {
            result.post.push_back(node->val);
        }
    }
    return result;
}

