#include <algorithm>
#include <vector>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
bool leaf(TreeNode* node) { return node && !node->left && !node->right; }
void addLeaves(TreeNode* node, vector<int>& out) {
    if (!node) return;
    if (leaf(node)) { out.push_back(node->val); return; }
    addLeaves(node->left, out);
    addLeaves(node->right, out);
}
vector<int> boundaryTraversal(TreeNode* root) {
    if (!root) return {};
    vector<int> answer{root->val};
    if (leaf(root)) return answer;
    for (TreeNode* p = root->left; p; p = p->left ? p->left : p->right)
        if (!leaf(p)) answer.push_back(p->val);
    addLeaves(root, answer); // root is not a leaf here
    vector<int> right;
    for (TreeNode* p = root->right; p; p = p->right ? p->right : p->left)
        if (!leaf(p)) right.push_back(p->val);
    reverse(right.begin(), right.end());
    answer.insert(answer.end(), right.begin(), right.end());
    return answer;
}

