vector<vector<int>> verticalTraversal(TreeNode* root) {
    if (!root) return {};
    map<int, map<int, multiset<int>>> columns;
    queue<tuple<TreeNode*, int, int>> q;
    q.push({root, 0, 0});
    while (!q.empty()) {
        auto [node, col, row] = q.front(); q.pop();
        columns[col][row].insert(node->val);
        if (node->left) q.push({node->left, col - 1, row + 1});
        if (node->right) q.push({node->right, col + 1, row + 1});
    }
    vector<vector<int>> answer;
    for (auto& [column, rows] : columns) {
        vector<int> values;
        for (auto& [row, samePosition] : rows)
            values.insert(values.end(), samePosition.begin(), samePosition.end());
        answer.push_back(values);
    }
    return answer;
}

