#include <algorithm>
#include <cstdint>
#include <queue>
#include <utility>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
unsigned long long widthOfBinaryTree(TreeNode* root) {
    if (!root) return 0;
    queue<pair<TreeNode*, unsigned long long>> q;
    q.push({root, 0});
    unsigned long long best = 0;
    while (!q.empty()) {
        int count = (int)q.size();
        unsigned long long base = q.front().second, last = 0;
        for (int i = 0; i < count; ++i) {
            auto [node, index] = q.front(); q.pop();
            index -= base; // normalize before doubling
            last = index;
            if (node->left) q.push({node->left, 2 * index + 1});
            if (node->right) q.push({node->right, 2 * index + 2});
        }
        best = max(best, last + 1);
    }
    return best; // assumes the mathematical width fits in 64 bits
}

