#include <queue>
#include <unordered_map>
#include <unordered_set>
#include <vector>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
vector<int> nodesAtDistanceK(TreeNode* root, TreeNode* target, int k) {
    if (!root || !target || k < 0) return {};
    unordered_map<TreeNode*, TreeNode*> parent;
    queue<TreeNode*> build;
    parent[root] = nullptr;
    build.push(root);
    while (!build.empty()) {
        TreeNode* node = build.front(); build.pop();
        if (node->left) { parent[node->left] = node; build.push(node->left); }
        if (node->right) { parent[node->right] = node; build.push(node->right); }
    }
    if (!parent.count(target)) return {}; // target must belong to this tree
    queue<TreeNode*> q;
    unordered_set<TreeNode*> seen{target};
    q.push(target);
    int distance = 0;
    while (!q.empty() && distance < k) {
        int width = (int)q.size();
        while (width--) {
            TreeNode* node = q.front(); q.pop();
            for (TreeNode* next : {node->left, node->right, parent[node]}) {
                if (next && seen.insert(next).second) q.push(next);
            }
        }
        ++distance;
    }
    vector<int> answer;
    while (!q.empty()) { answer.push_back(q.front()->val); q.pop(); }
    return answer;
}

