int burnTime(TreeNode* root, int targetValue) {
    if (!root) return -1;
    unordered_map<TreeNode*, TreeNode*> parent;
    queue<TreeNode*> build;
    build.push(root);
    parent[root] = nullptr;
    TreeNode* target = nullptr;
    while (!build.empty()) {
        TreeNode* node = build.front(); build.pop();
        if (!target && node->val == targetValue) target = node;
        if (node->left) { parent[node->left] = node; build.push(node->left); }
        if (node->right) { parent[node->right] = node; build.push(node->right); }
    }
    if (!target) return -1;
    queue<TreeNode*> fire;
    unordered_set<TreeNode*> seen{target};
    fire.push(target);
    int minutes = -1;
    while (!fire.empty()) {
        int width = (int)fire.size();
        ++minutes; // all nodes in this layer ignite together
        while (width--) {
            TreeNode* node = fire.front(); fire.pop();
            for (TreeNode* next : {node->left, node->right, parent[node]})
                if (next && seen.insert(next).second) fire.push(next);
        }
    }
    return minutes; // assumes node values identify the intended target
}

