#include <stdexcept>
#include <unordered_map>
#include <vector>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
TreeNode* buildPre(const vector<int>& preorder, int& cursor,
                   int left, int right, const unordered_map<int,int>& position) {
    if (left > right) return nullptr;
    if (cursor >= (int)preorder.size()) throw invalid_argument("invalid traversals");
    int value = preorder[cursor++];
    auto it = position.find(value);
    if (it == position.end() || it->second < left || it->second > right)
        throw invalid_argument("invalid traversals");
    TreeNode* root = new TreeNode{value, nullptr, nullptr};
    root->left = buildPre(preorder, cursor, left, it->second - 1, position);
    root->right = buildPre(preorder, cursor, it->second + 1, right, position);
    return root;
}
