    unordered_map<int,int> position;
    for (int i = 0; i < (int)inorder.size(); ++i)
        if (!position.emplace(inorder[i], i).second)
            throw invalid_argument("values must be distinct");
    int cursor = 0;
    TreeNode* root = buildPre(preorder, cursor, 0, (int)inorder.size() - 1, position);
    if (cursor != (int)preorder.size()) throw invalid_argument("invalid traversals");
