                    int left, int right, const unordered_map<int,int>& position) {
    if (left > right) return nullptr;
    if (cursor < 0) throw invalid_argument("invalid traversals");
    int value = postorder[cursor--];
    auto it = position.find(value);
    if (it == position.end() || it->second < left || it->second > right)
        throw invalid_argument("invalid traversals");
    TreeNode* root = new TreeNode{value, nullptr, nullptr};
    root->right = buildPost(postorder, cursor, it->second + 1, right, position);
    root->left = buildPost(postorder, cursor, left, it->second - 1, position);
    return root;
}
TreeNode* buildFromPostIn(const vector<int>& postorder, const vector<int>& inorder) {
    if (postorder.size() != inorder.size()) throw invalid_argument("size mismatch");
    unordered_map<int,int> position;
    for (int i = 0; i < (int)inorder.size(); ++i)
        if (!position.emplace(inorder[i], i).second)
            throw invalid_argument("values must be distinct");
    int cursor = (int)postorder.size() - 1;
    TreeNode* root = buildPost(postorder, cursor, 0, (int)inorder.size() - 1, position);
    if (cursor != -1) throw invalid_argument("invalid traversals");
    return root;
}

