#include <queue>
#include <sstream>
#include <string>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
string serialize(TreeNode* root) {
    if (!root) return "#,";
    queue<TreeNode*> q;
    q.push(root);
    string data;
    while (!q.empty()) {
        TreeNode* node = q.front(); q.pop();
        if (!node) { data += "#,"; continue; }
        data += to_string(node->val) + ",";
        q.push(node->left);
        q.push(node->right);
    }
    return data;
}
TreeNode* deserialize(const string& data) {
    istringstream in(data);
    string token;
    if (!getline(in, token, ',') || token == "#") return nullptr;
    TreeNode* root = new TreeNode{stoi(token), nullptr, nullptr};
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* node = q.front(); q.pop();
        if (getline(in, token, ',') && token != "#") {
            node->left = new TreeNode{stoi(token), nullptr, nullptr};
            q.push(node->left);
        }
        if (getline(in, token, ',') && token != "#") {
            node->right = new TreeNode{stoi(token), nullptr, nullptr};
            q.push(node->right);
        }
    }
    return root;
}

